window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5d6979a898879adb"]={"versions": [{"id": "FIG-5d6979a898879adb", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Scheduling- und Timing-Ablaufdiagramm (Gantt-artiger CPU-Ausführungszeitstrahl mit diskreter Taktskala) im Kontext des AUTOSAR OS (Classic Platform, BSW, System Services). Das Diagramm illustriert das architektonische Rationale hinter den AUTOSAR-OS-Timing-Protection-Mechanismen und demonstriert die Unzulänglichkeit reiner Deadline-Überwachung (Deadline Monitoring) in einem festpriorisierten, präemptiven Betriebssystem (Fixed Priority Preemptive Scheduling).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Tasks (Scheduling-Entitäten):</strong>\n<ul class=\"fig-list\"><li><code>Task A</code>: Höchste Priorität, präemptiert Task B und Task C.\n</li><li><code>Task B</code>: Mittlere Priorität, präemptiert Task C.\n</li><li><code>Task C</code>: Niedrigste Priorität.\n</li></ul>\n</li><li><strong>Grafische Elemente und Farbcodierung:</strong>\n<ul class=\"fig-list\"><li><em>Graue Blöcke:</em> Spezifikationskonforme Ausführungsintervalle (Execution Budget im Rahmen der Vorgaben).\n</li><li><em>Rote Blöcke:</em> Spezifikationsverletzungen durch Ausführungszeitüberschreitung (Execution Budget Violation) bei Task A und Task B.\n</li><li><em>Rotes Ausrufezeichen:</em> Zeitpunkt des Verpassens der Frist (Deadline Miss) von Task C bei Zeittakt 15.\n</li><li><em>Grüner Block:</em> Spezifikationskonforme, aber verspätete Restlaufzeit von Task C (1 Zeittakt nach Ablauf der Deadline).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; OS-Parameter:</strong>\n<ul class=\"fig-list\"><li>Diskrete Zeitachse (Ticks 0 bis 17).\n</li><li>Task-Aktivierung / Release-Zeitpunkt (Inter-Arrival Time).\n</li><li>Präemptiver Scheduler und Überwachungsinstanzen (Timing Protection / Protection Hook).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>T=1 bis T=2:</strong> Task A wird aktiviert und belegt die CPU für 1 Zeittakt spezifikationsgemäß.\n</li><li><strong>T=2 bis T=4:</strong> Task B führt für 2 Zeittakte regulär aus.\n</li><li><strong>T=4 bis T=5:</strong> Task B überschreitet sein Ausführungsbudget um 1 Zeittakt (roter Block), hält jedoch seine eigene Deadline ein.\n</li><li><strong>T=5 bis T=7:</strong> Task A wird erneut aktiviert; Ausführung von T=5 bis T=6 regulär, von T=6 bis T=7 überschreitet Task A sein Ausführungsbudget um 1 Zeittakt (roter Block), erfüllt jedoch seine Deadline.\n</li><li><strong>T=7 bis T=8:</strong> Task C erhält erstmals Rechenzeit und führt 1 Zeittakt regulär aus.\n</li><li><strong>T=8:</strong> Task B trifft vorzeitig ein (Inter-Arrival-Time-Verletzung bei T=8 statt T=10), präemptiert Task C und führt bis T=10 aus (2 Ticks).\n</li><li><strong>T=10 bis T=11:</strong> Task A wird aktiviert, präemptiert Task B und führt für 1 Zeittakt regulär aus.\n</li><li><strong>T=11 bis T=12:</strong> Task B nimmt die CPU wieder auf, beendet seine Ausführung und hält seine Deadline trotz Vorverlegung ein.\n</li><li><strong>T=12 bis T=15:</strong> Task C setzt die Abarbeitung für 3 Zeittakte fort.\n</li><li><strong>T=15:</strong> Deadline von Task C läuft ab. Task C hat zu diesem Zeitpunkt 4 von 5 benötigten Ticks abgearbeitet; es verbleibt 1 Tick Restlaufzeit (grüner Block von T=15 bis T=16). Bei T=15 tritt ein Deadline Miss auf, obwohl Task C vollkommen spezifikationskonform agiert hat.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Rationale:</strong> Das Schaubild begründet normativ die Anforderung an AUTOSAR OS, timing-bezogene Fehlerquellen an ihrem Ursprung abzufangen, anstatt sich auf reine Deadline-Überwachungen zu stützen. Bei ausschließlichem Deadline Monitoring würde die unschuldige, niederpriorisierte Task C sanktioniert, während die tatsächlichen Verursacher (Task A mit Budgetüberschreitung, Task B mit Budgetüberschreitung und Rate-Limiting-Verletzung) unentdeckt bleiben.\n</li><li><strong>Entwickler- &amp; Konfigurationshinweise:</strong>\n<ul class=\"fig-list\"><li>Konfiguration von <code>OsTaskExecutionBudget</code> bzw. <code>OsIsrExecutionBudget</code> zur Kapselung von Worst-Case Execution Time (WCET)-Verletzungen.\n</li><li>Konfiguration von <code>OsTaskTimeFrame</code> bzw. <code>OsIsrTimeFrame</code> zur Unterbindung unzulässig hoher Aktivierungsraten (Inter-Arrival Time Protection).\n</li><li>Definition des <code>ProtectionHook</code> zur Behandlung von Timing-Verstößen (z. B. Beenden fehlerhafter Tasks oder Partition-Restarts), bevor niederpriorisierte Tasks im Gesamtsystem verhungern oder Deadlines verpassen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f6e39a681c8edb82", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Scheduling- und Timing-Ablaufdiagramm (Gantt-artiger CPU-Ausführungszeitstrahl mit diskreter Taktskala) im Kontext des AUTOSAR OS (Classic Platform, BSW, System Services). Das Diagramm illustriert das architektonische Rationale hinter den AUTOSAR-OS-Timing-Protection-Mechanismen und demonstriert die Unzulänglichkeit reiner Deadline-Überwachung (Deadline Monitoring) in einem festpriorisierten, präemptiven Betriebssystem (Fixed Priority Preemptive Scheduling).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Tasks (Scheduling-Entitäten):</strong>\n<ul class=\"fig-list\"><li><code>Task A</code>: Höchste Priorität, präemptiert Task B und Task C.\n</li><li><code>Task B</code>: Mittlere Priorität, präemptiert Task C.\n</li><li><code>Task C</code>: Niedrigste Priorität.\n</li></ul>\n</li><li><strong>Grafische Elemente und Farbcodierung:</strong>\n<ul class=\"fig-list\"><li><em>Graue Blöcke:</em> Spezifikationskonforme Ausführungsintervalle (Execution Budget im Rahmen der Vorgaben).\n</li><li><em>Rote Blöcke:</em> Spezifikationsverletzungen durch Ausführungszeitüberschreitung (Execution Budget Violation) bei Task A und Task B.\n</li><li><em>Rotes Ausrufezeichen:</em> Zeitpunkt des Verpassens der Frist (Deadline Miss) von Task C bei Zeittakt 15.\n</li><li><em>Grüner Block:</em> Spezifikationskonforme, aber verspätete Restlaufzeit von Task C (1 Zeittakt nach Ablauf der Deadline).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; OS-Parameter:</strong>\n<ul class=\"fig-list\"><li>Diskrete Zeitachse (Ticks 0 bis 17).\n</li><li>Task-Aktivierung / Release-Zeitpunkt (Inter-Arrival Time).\n</li><li>Präemptiver Scheduler und Überwachungsinstanzen (Timing Protection / Protection Hook).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>T=1 bis T=2:</strong> Task A wird aktiviert und belegt die CPU für 1 Zeittakt spezifikationsgemäß.\n</li><li><strong>T=2 bis T=4:</strong> Task B führt für 2 Zeittakte regulär aus.\n</li><li><strong>T=4 bis T=5:</strong> Task B überschreitet sein Ausführungsbudget um 1 Zeittakt (roter Block), hält jedoch seine eigene Deadline ein.\n</li><li><strong>T=5 bis T=7:</strong> Task A wird erneut aktiviert; Ausführung von T=5 bis T=6 regulär, von T=6 bis T=7 überschreitet Task A sein Ausführungsbudget um 1 Zeittakt (roter Block), erfüllt jedoch seine Deadline.\n</li><li><strong>T=7 bis T=8:</strong> Task C erhält erstmals Rechenzeit und führt 1 Zeittakt regulär aus.\n</li><li><strong>T=8:</strong> Task B trifft vorzeitig ein (Inter-Arrival-Time-Verletzung bei T=8 statt T=10), präemptiert Task C und führt bis T=10 aus (2 Ticks).\n</li><li><strong>T=10 bis T=11:</strong> Task A wird aktiviert, präemptiert Task B und führt für 1 Zeittakt regulär aus.\n</li><li><strong>T=11 bis T=12:</strong> Task B nimmt die CPU wieder auf, beendet seine Ausführung und hält seine Deadline trotz Vorverlegung ein.\n</li><li><strong>T=12 bis T=15:</strong> Task C setzt die Abarbeitung für 3 Zeittakte fort.\n</li><li><strong>T=15:</strong> Deadline von Task C läuft ab. Task C hat zu diesem Zeitpunkt 4 von 5 benötigten Ticks abgearbeitet; es verbleibt 1 Tick Restlaufzeit (grüner Block von T=15 bis T=16). Bei T=15 tritt ein Deadline Miss auf, obwohl Task C vollkommen spezifikationskonform agiert hat.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Rationale:</strong> Das Schaubild begründet normativ die Anforderung an AUTOSAR OS, timing-bezogene Fehlerquellen an ihrem Ursprung abzufangen, anstatt sich auf reine Deadline-Überwachungen zu stützen. Bei ausschließlichem Deadline Monitoring würde die unschuldige, niederpriorisierte Task C sanktioniert, während die tatsächlichen Verursacher (Task A mit Budgetüberschreitung, Task B mit Budgetüberschreitung und Rate-Limiting-Verletzung) unentdeckt bleiben.\n</li><li><strong>Entwickler- &amp; Konfigurationshinweise:</strong>\n<ul class=\"fig-list\"><li>Konfiguration von <code>OsTaskExecutionBudget</code> bzw. <code>OsIsrExecutionBudget</code> zur Kapselung von Worst-Case Execution Time (WCET)-Verletzungen.\n</li><li>Konfiguration von <code>OsTaskTimeFrame</code> bzw. <code>OsIsrTimeFrame</code> zur Unterbindung unzulässig hoher Aktivierungsraten (Inter-Arrival Time Protection).\n</li><li>Definition des <code>ProtectionHook</code> zur Behandlung von Timing-Verstößen (z. B. Beenden fehlerhafter Tasks oder Partition-Restarts), bevor niederpriorisierte Tasks im Gesamtsystem verhungern oder Deadlines verpassen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5d6979a898879adb", "to": "FIG-f6e39a681c8edb82", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
